// Ed25519 verification of server-signed entitlements.
//
// The server signs every entitlement payload it returns. This module verifies
// the signature with the app's embedded public key before the cache is trusted
// offline — a user editing the local cache cannot forge a premium entitlement.

// Matches the dev keypair in python-server/.entitlement_ed25519.key.
// The PRODUCTION build MUST set VITE_ENTITLEMENT_PUBLIC_KEY (generated by
// python-server/scripts/generate_entitlement_keys.py); otherwise the dev key
// is used as a fallback so local development keeps working.
const DEV_PUBLIC_KEY_B64 = 'thjmQF42nalyE5amyCaTboxXsL0AStbZtg6VpoLXsPM=';

const PUBLIC_KEY_B64 = (import.meta.env.VITE_ENTITLEMENT_PUBLIC_KEY || DEV_PUBLIC_KEY_B64).trim();

export interface EntitlementPayload {
  user_id: string;
  entitlement: string;
  plan_type: string;
  status: string;
  access_until: string | null;
  last_verified_at: string | null;
  grace_until: string | null;
  features_enabled: string[];
}

export function canonicalize(obj: Record<string, unknown>): string {
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(obj).sort()) {
    sorted[key] = obj[key];
  }
  return JSON.stringify(sorted);
}

let cachedKey: CryptoKey | null = null;

async function getKey(): Promise<CryptoKey> {
  if (cachedKey) return cachedKey;
  const raw = Uint8Array.from(atob(PUBLIC_KEY_B64), (c) => c.charCodeAt(0));
  cachedKey = await crypto.subtle.importKey('raw', raw, { name: 'Ed25519' }, false, ['verify']);
  return cachedKey;
}

export async function verifyEntitlementSignature(payload: object): Promise<boolean> {
  const rec = payload as Record<string, unknown>;
  if (typeof rec.signature !== 'string') return false;
  const signature = rec.signature;
  const { signature: _signature, ...rest } = rec;
  try {
    if (!crypto.subtle) return false;
    const key = await getKey();
    const message = new TextEncoder().encode(canonicalize(rest));
    const sigBytes = Uint8Array.from(atob(signature), (c) => c.charCodeAt(0));
    return await crypto.subtle.verify('Ed25519', key, sigBytes, message);
  } catch (e) {
    console.warn('[Entitlement] signature verification failed:', e);
    return false;
  }
}